package com.example.movietickets.config;
import com.example.movietickets.model.*; import com.example.movietickets.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*; import java.util.*;
@Configuration public class DataInitializer {
 @Bean CommandLineRunner seed(MovieRepository movies, ShowtimeRepository showtimes, UserRepository users, PasswordEncoder encoder){return args->{if(!users.existsByEmailIgnoreCase("admin@catchmyshow.com")) users.save(new User("admin@catchmyshow.com",encoder.encode("admin123"),"CatchMyShow Admin",User.Role.ADMIN)); if(!users.existsByEmailIgnoreCase("customer@reelseat.com")) users.save(new User("customer@reelseat.com",encoder.encode("customer123"),"Demo Customer",User.Role.CUSTOMER)); showtimes.findAll().forEach(s->{s.migratePricing();showtimes.save(s);}); if(movies.count()>0)return; Movie m1=movies.save(new Movie("Interstellar","Sci-Fi · Adventure",169,"A team of explorers travels through a wormhole in space in an attempt to ensure humanity's survival.","https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=900&q=80",8.7,true)); Movie m2=movies.save(new Movie("The Grand Budapest Hotel","Comedy · Drama",99,"A legendary concierge and his lobby boy become friends and adventure across a changing Europe.","https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=900&q=80",8.1,true)); Movie m3=movies.save(new Movie("Spider-Man: Into the Spider-Verse","Animation · Action",117,"Teen Miles Morales becomes Spider-Man of his reality and crosses paths with counterparts from other dimensions.","https://images.unsplash.com/photo-1531259683007-016a7b628fc3?auto=format&fit=crop&w=900&q=80",8.4,false)); Movie m4=movies.save(new Movie("La La Land","Musical · Romance",128,"A jazz pianist and an aspiring actress fall in love while pursuing their dreams in Los Angeles.","https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=900&q=80",8.0,false)); LocalDate today=LocalDate.now(); List<Movie> ms=List.of(m1,m2,m3,m4); for(int i=0;i<ms.size();i++){Movie m=ms.get(i); for(int j=0;j<4;j++) showtimes.save(new Showtime(m,LocalDateTime.of(today.plusDays(j%2),LocalTime.of(10+j*3,30)),"Screen "+(i%3+1),180.0+i*30));}};}
}
